import { Component, EventEmitter, Input, Output } from '@angular/core';


@Component({
  selector: 'app-custom-pagination', // Define the selector to use in templates
  templateUrl: './custom-pagination.component.html', // Link to the template
  styleUrls: ['./custom-pagination.component.scss'], // Link to styles (optional)
})
export class CustomPaginationComponent {
  @Input() pagination: any; // Input property to receive pagination data
  @Output() pageChange = new EventEmitter<number>(); // Output event to emit page change

  changePage(page: number) {
    if (page >= 1 && page <= this.pagination.total_pages) {
      this.pageChange.emit(page);
    }
  }
}
